mkdir -p 'integrations/public-todo/fixtures'
cat >'integrations/public-todo/fixtures/ambiguous.yaml' <<'REGISTRYCTL_INTEGRATIONS_PUBLIC_TODO_FIXTURES_AMBIGUOUS_YAML_EOF'
name: ambiguous-todo
classification: synthetic
